# One-time application of the exact locally linted and tested review delta.
import base64, hashlib, lzma, subprocess
payload = ''''''
patch = lzma.decompress(base64.b64decode(payload, validate=True))
assert hashlib.sha256(patch).hexdigest() == 'bea575960da6071b9a7af419a4f8c744630d4e1bfc0f5757c68b726b53afabfa'
subprocess.run(['git','apply','--check','-'], input=patch, check=True)
subprocess.run(['git','apply','-'], input=patch, check=True)
